html:
{#- Permintaan penawaran ke supplier, dicetak dari Request for Quotation -#}

{%- set material_requests = doc.items | map(attribute="material_request") | select | unique | list -%}

<style>
	/* tiga kolom terakhir diisi tangan sama supplier, jadi dikasih kotak dan ruang nulis */
	.vic-pf .items .fill { border-left: 1px solid #999; }
	/* garis pemisah antara Description dan Qty */
	.vic-pf .items .qty-col { border-left: 1px solid #999; }
	.vic-pf .items tbody td { height: 30px; }
</style>

<div class="vic-pf">
	{%- include "vic_addon/templates/print_formats/vic_letterhead.html" -%}

	<div class="title-wrap">
		<div class="title-block">
			<div class="doc-title">INQUIRY</div>
			<table class="meta">
				<tr>
					<td class="lbl">Inquiry No.</td>
					<td class="sep">:</td>
					<td>{{ doc.name }}</td>
				</tr>
				<tr>
					<td class="lbl">Date</td>
					<td class="sep">:</td>
					<td>{{ frappe.utils.formatdate(doc.transaction_date, "MMMM d, yyyy") }}</td>
				</tr>
				{%- if material_requests %}
					<tr>
						<td class="lbl">Our Ref</td>
						<td class="sep">:</td>
						<td>{{ material_requests | join(", ") }}</td>
					</tr>
				{%- endif %}
			</table>
		</div>
	</div>

	{#- Project & Subject cuma dicetak kalau centangan Show ... in Print-nya nyala -#}
	{%- set show_project = doc.get("project") and doc.get("custom_show_project") %}
	{%- set show_subject = doc.get("custom_subject") and doc.get("custom_show_subject") %}
	{%- if show_project or show_subject %}
		<table class="terms">
			{%- if show_project %}
				<tr>
					<td class="lbl">Project</td>
					<td class="sep">:</td>
					<td>{{ frappe.db.get_value("Project", doc.project, "project_name") or doc.project }}</td>
				</tr>
			{%- endif %}
			{%- if show_subject %}
				<tr>
					<td class="lbl">Subject</td>
					<td class="sep">:</td>
					<td>{{ doc.custom_subject }}</td>
				</tr>
			{%- endif %}
		</table>
	{%- endif %}

	<div class="note">Please quote us your best price &amp; delivery time as follows :</div>

	<table class="items">
		<thead>
			<tr>
				<th style="width: 6%">Item</th>
				<th class="left" style="width: 34%">Description</th>
				<th class="qty-col" style="width: 12%">Qty</th>
				<th class="fill" style="width: 18%">Unit Price</th>
				<th class="fill" style="width: 12%">Weight</th>
				<th class="fill" style="width: 18%">Remarks</th>
			</tr>
		</thead>
		<tbody>
			{%- set ns = namespace(no = 0) %}
			{%- for group in group_items(doc.items) %}
				{#- Pengiriman paling atas, di bawahnya Pengerjaan, terus item - gak ada yang menjorok
				    (lihat vic/item_header.py). Judulnya mulai di kolom Description. -#}
				{%- if group.pengiriman %}
					<tr class="group pengiriman"><td></td><td class="text" colspan="5">{{ group.pengiriman }}</td></tr>
				{%- endif %}
				{%- if group.pengerjaan %}
					<tr class="group"><td></td><td class="text" colspan="5">{{ group.pengerjaan }}</td></tr>
				{%- endif %}
				{%- for item in group.rows %}
					{%- set ns.no = ns.no + 1 %}
					{%- set size = frappe.db.get_value("Item", item.item_code, "custom_size") %}
					{%- set qty = item.qty | float %}
					<tr>
						<td class="num">{{ ns.no }}</td>
						<td class="text">
							<div class="desc">{{ get_item_description(item) }}</div>
							{%- if size %}<div>Size : {{ size }}</div>{% endif %}
						</td>
						<td class="qty qty-col">{{ qty | int if qty == qty | round(0) else "%.2f" | format(qty) }} {{ item.uom }}</td>
						{#- Unit Price sengaja kosong, itu jatah supplier yang ngisi -#}
						<td class="fill money"></td>
						<td class="fill qty">{{ item.get("custom_weight") or "" }}</td>
						<td class="fill">{{ item.get("custom_remarks") or "" }}</td>
					</tr>
				{%- endfor %}
			{%- endfor %}
		</tbody>
	</table>

	<div class="note">Wait for your reply immediately</div>

	<table class="sign">
		<tr>
			<td style="width: 60%"></td>
			<td>
				<div>Best regards,</div>
				<div class="role"></div>
				{#- Best Regards -> Person in Charge -> nama user yang bikin -#}
				<div>{{ get_inquiry_signatory(doc) }}</div>
			</td>
		</tr>
	</table>
	{%- include "vic_addon/templates/print_formats/vic_footer.html" -%}
</div>
